fileBaselines.content:
@import './colors.css';

* {
    border: none;
    border-radius: 0;

    font-family: "JetBrainMono Nerd Font Propo";
    font-weight: bold;
    font-size: 13px;

    min-height: 0px;
    padding: 0px;
    margin: 0px;

}

window#waybar {
 background: transparent;

}

tooltip {
   background: @bg0;
   border: 1px solid @bg3;
   border-radius: 12px;
}

tooltip label {
    color:  @fg;
    padding: 6px;

}


#workspaces {
    background-color: @bg0;
    padding: 5px 3px;
    margin: 0 0 0 12px;
    border-radius: 18px;
    border: 1px solid @bg1;
    color:@fg;

}

#workspaces button {
    padding: 0px 6px;
    margin: 0px 3px;
    border-radius: 0px;
    color: transparent;
    background-color: @bg1;
    transition: all 0.3s ease-in-out;
}

#workspaces button:hover {
    color: @bg0;
    background-color: @blue;
    min-width: 50px;
    transition: all 0.3s ease-in-out;
    font-size: 13px;
}

#`workspaces button:hover {
    color: @bg0;
    background-color: @purple;
    border-radius: 16px;
    min-width: 50px;
    backgroud-size: 400% 400%;

}

#workspaeces button.urgent {
    color: @bg0;
    background-color: @red;
    border-radius: 16px;
    min-width: 50px;
    backgroud-size: 400% 400%;
    transition: all 0.3s ease-in-out;
}

#battery,
#pulseaudio,
#network,
#clock ,
#custom-notification {
    background-color: @bg0;
    padding: 0px 15px 0px 15px;
    margin: 0 0 0 12px;
    border-radius: 50px;
    border: 1px solid @bg1;
}

#clock {
    color: @blue;
}

#custom-notification {
    color: @fg;
    margin: 0 12px 0 12px;
}

#pulseaudio {
    color: @yellow;
}

#network {
    color: @purple;
}

#battery {
    color: @green;
}

